import difflib
import re

from ta_emil_cli_aatrace_parser.sack_downloader import SackDownloader

from .build_parser import parse_out_all_builds
from .logger_config import log


class SackDownloaderBestMatch(SackDownloader):
    def __init__(self):
        super(SackDownloaderBestMatch, self).__init__()
        log.debug("eNB build: {}".format(self.enb_sw_build))
        build_re = re.compile(r"(.*?/)\s+(\d+-.*?\d+\s\d+:\d+)\s+-")
        all_builds_tuple = parse_out_all_builds(
            build_address_page=self.base_cloud_agent_sw_build_url, build_re=build_re
        )
        all_build_names_list = [build.name for build in all_builds_tuple]
        possible_matches = difflib.get_close_matches(
            self.enb_sw_build, all_build_names_list, n=10, cutoff=0.6
        )
        self.enb_sw_build = get_best_match(self.enb_sw_build, possible_matches)
        log.debug("Found best matching sack: {}".format(self.enb_sw_build))
        self.sack_download_url = (
            self.base_cloud_agent_sw_build_url
            + self.enb_sw_build
            + "/"
            + self.enb_sw_build
            + "_ida.zip"
        )
        self.sack_zip_path = self.output_directory + self.enb_sw_build + "_ida.zip"


def get_best_match(base_build_name, matches):
    """to be created"""
    parts = base_build_name.split("_")
    weights = [10**w for w in range(len(parts), 0, -1)]
    best_match_weight = 0
    best_match_index = None
    for i, possible_match in enumerate(matches):
        current_weight = 0
        possible_parts = possible_match.split("_")
        for base_part, candidate_part, weight in zip(parts, possible_parts, weights):
            if base_part == candidate_part:
                current_weight += weight
        if current_weight > best_match_weight:
            best_match_weight = current_weight
            best_match_index = i
    return matches[best_match_index]
